"""Summarize radix review without adopting semantics or changing admission."""
from pathlib import Path
import json,re
C=Path(__file__).resolve().parent;E=C/'evidence'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
original=load(E/'probe-receipts.json');controls=load(E/'control-receipts.json');full=load(E/'format-integer-review-receipt.json');assert len(original)==17 and len(controls)==34
for r in original+controls:assert r['exitCode']==0 and not r['timeout']
