assert sum(r['result']['kind']=='Passed' for r in original)==2 and sum(r['result']['kind']=='Failed' for r in original)==15
assert {r['result']['Name'] for r in original if r['result']['kind']=='Passed'}=={'format-integer-40-014','format-integer-40-015'}
qt3=[r for r in controls if r['result']['Suite']=='qt3'];qt4=[r for r in controls if r['result']['Suite']=='qt4'];assert len(qt3)==len(qt4)==17 and all(r['result']['kind']=='Passed' for r in qt3)
assert sum(r['result']['kind']=='Passed' for r in qt4)==8 and sum(r['result']['kind']=='Failed' for r in qt4)==9
for suffix in ['parse-hex','parse-binary']:
 r=next(r for r in qt4 if r['result']['Name'].endswith(suffix));assert r['result']['kind']=='Failed' and 'XPST0017' in r['result']['message']
r=next(r for r in qt4 if r['result']['Name'].endswith('lookup-parse'));assert r['result']['kind']=='Failed' and 'false' in r['result']['message']
formatter=[r['result']['Name'] for r in original if r['result']['kind']=='Failed' and r['result']['Name']!='format-integer-40-012'];assert len(formatter)==14
